foundations-colors--specs.content:
import { Meta, ColorPalette, ColorItem } from '@storybook/addon-docs/blocks';

import { ThemeProvider } from 'storybook/theming';
import { theme } from '@dt-dds/react';

<Meta title='Foundations/Colors' />

# Default

export const colors = Object.entries(theme.colors).reduce(
  (acc, [key, value]) => {
    const groupedKey =
      key.indexOf('_') > 0 ? key.substring(0, key.indexOf('_')) : key;
    const group = acc[groupedKey] ?? [];
    return {
      ...acc,
      [groupedKey]: [
        ...group,
        {
          [key]: value,
        },
      ],
    };
  },
  {}
);

<div style={{ background: '#eeeeee', padding: '20px' }}>
  <ThemeProvider theme={theme}>
    <ColorPalette>
      {Object.entries(colors).map(([k, v]) => {
        return <ColorItem key={k} title={k} colors={Object.assign({}, ...v)} />;
      })}
    </ColorPalette>
  </ThemeProvider>
</div>

foundations-palette--specs.content:
import { Meta, ColorPalette, ColorItem } from '@storybook/addon-docs/blocks';

import { ThemeProvider } from 'storybook/theming';

import { theme as defaultTheme } from '@dt-dds/react';

import { greenlaneTheme, truckAPITheme } from '../../.storybook/themes';

<Meta title='Foundations/Palette' />

export const themes = [
  { name: 'Daimler (default)', theme: defaultTheme },
  { name: 'Greenlane', theme: greenlaneTheme },
  { name: 'TruckAPI', theme: truckAPITheme },
];

export const getColors = (theme) =>
  Object.entries(theme.palette).reduce((acc, [key, value]) => {
    const group = acc[key] ?? [];
    return {
      ...acc,
      [key]: [
        ...group,
        {
          ...value,
        },
      ],
    };
  }, {});

<div>
  {themes.map(({ name, theme }) => (
    <div key={name}>
      <h1>{name}</h1>
      <div style={{ background: '#eeeeee', padding: '20px' }}>
        <ThemeProvider theme={theme}>
          <ColorPalette>
            {Object.entries(getColors(theme)).map(([k, v]) => {
              return (
                <ColorItem key={k} title={k} colors={Object.assign({}, ...v)} />
              );
            })}
          </ColorPalette>
        </ThemeProvider>
      </div>
    </div>
  ))}
</div>
